describe('Password Requirements Tooltip', () => {
    beforeEach(() => {
        cy.visit('/login'); // Adjust the URL to your application's login page
    });

    it('should display the tooltip with password requirements on focus', () => {
        cy.get('input[name="password"]').focus();
        cy.get('.tooltip').should('be.visible')
            .and('contain', 'Password must be at least 8 characters long, include an uppercase letter, a number, and a special character.');
    });

    it('should not display the tooltip when the password input is not focused', () => {
        cy.get('input[name="username"]').focus(); // Focus on another input
        cy.get('.tooltip').should('not.exist');
    });
});
